#![cfg(test)]
//! Guards for Candler's default statistics. The `t1_` guards compare each method with the values
//! that scipy and statsmodels wrote into `tests/vectors/stats/*.toml` (regenerated by
//! `gen_stats.py`, which reads no Candler file); a vector row is never edited to make a guard
//! pass.

use std::path::PathBuf;

use candler_core::analysis::error::StatsError;
use candler_core::analysis::fisher::{TIE_TOLERANCE, fisher_two_sided};
use candler_core::analysis::holm::{holm, rejected};
use candler_core::analysis::newcombe::newcombe_difference;
use candler_core::analysis::tally::{ArmTally, Omitted, RunFacts, tally};
use candler_core::analysis::wilson::{Counts, wilson};
use candler_core::analysis::{ALPHA, z_two_sided};
use candler_core::evaluation::selection::rates::{CellKey, Rates, rates};
use candler_core::evaluation::selection::select::select;
use candler_schemas::execution::{Integrity, InvalidReason};
use candler_schemas::outcome::{
    Cause, OutcomeRecord, OutcomeRecordBuilder, Role, Status, Value, Weight,
};
use candler_schemas::primitives::{Digest, ExpectationId, NameVersion, RequestId, RunKey};
use rand_chacha::ChaCha8Rng;
use rand_chacha::rand_core::{Rng as _, SeedableRng as _};
use serde::Deserialize;
use serde::de::DeserializeOwned;
use statrs::distribution::{Binomial, Discrete as _};
use std::collections::BTreeMap;

#[derive(Deserialize)]
struct Vectors<R> {
    rows: Vec<R>,
}

/// The rows of one vector file, in file order.
fn vector<R: DeserializeOwned>(file: &str) -> Vec<R> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/vectors/stats")
        .join(file);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let parsed: Vectors<R> = toml::from_str(&text).unwrap_or_else(|e| panic!("{file}: {e}"));
    assert!(!parsed.rows.is_empty(), "{file} has no rows");
    parsed.rows
}

fn counts(k: u64, n: u64) -> Counts {
    Counts::new(k, n).unwrap_or_else(|e| panic!("counts {k}/{n}: {e}"))
}

fn close(label: &str, got: f64, want: f64, tolerance: f64) {
    assert!(
        (got - want).abs() <= tolerance,
        "{label}: got {got:?}, the second engine has {want:?} (tolerance {tolerance:e})"
    );
}

#[derive(Deserialize)]
struct WilsonRow {
    k: u64,
    n: u64,
    lo: f64,
    hi: f64,
}

#[derive(Deserialize)]
struct FisherRow {
    k1: u64,
    n1: u64,
    k2: u64,
    n2: u64,
    p: f64,
    tie: bool,
}

#[derive(Deserialize)]
struct NewcombeRow {
    k1: u64,
    n1: u64,
    k2: u64,
    n2: u64,
    diff: f64,
    lo: f64,
    hi: f64,
}

#[derive(Deserialize)]
struct HolmRow {
    p: Vec<f64>,
    adjusted: Vec<f64>,
}

/// Checks one Fisher row: the p-value and its side of alpha.
fn check_fisher(row: &FisherRow) {
    let label = format!("fisher {}/{} against {}/{}", row.k1, row.n1, row.k2, row.n2);
    let got = fisher_two_sided(counts(row.k1, row.n1), counts(row.k2, row.n2))
        .unwrap_or_else(|e| panic!("{label}: {e}"));
    close(&label, got, row.p, 1e-10);
    assert_eq!(
        got < ALPHA,
        row.p < ALPHA,
        "{label}: p = {got:?} and the second engine's {:?} fall on different sides of alpha",
        row.p
    );
}

/// Guards: the Wilson 95 % limits for 179 (k, n) pairs, n from 1 to 100 and every k, agree with
/// the second engine to 1e-9, so a Wald interval, a hard-coded z or a continuity correction is
/// seen.
/// Oracle: statsmodels `proportion_confint(method="wilson")`, which the generator cross-checked
/// against scipy's `binomtest(..).proportion_ci(method="wilson")`.
/// Bite: the Wald interval in place of Wilson; `z` written as 1.96.
#[test]
fn t1_wilson_matches_the_second_engine() {
    for row in vector::<WilsonRow>("wilson.toml") {
        let label = format!("wilson {}/{}", row.k, row.n);
        let got = wilson(counts(row.k, row.n)).unwrap_or_else(|e| panic!("{label}: {e}"));
        close(&format!("{label} lo"), got.lo(), row.lo, 1e-9);
        close(&format!("{label} hi"), got.hi(), row.hi, 1e-9);
    }
}

/// Guards: the normal quantile behind every Wilson and Newcombe limit is the exact 0.975
/// quantile, not its two-digit rounding.
/// Oracle: `scipy.stats.norm.ppf(0.975)`, written as a literal.
/// Bite: `z` written as 1.96.
#[test]
fn t1_z_is_the_normal_quantile() {
    let z = z_two_sided().unwrap_or_else(|e| panic!("z: {e}"));
    close("z", z, 1.959_963_984_540_054, 1e-12);
}

/// Guards: Fisher's two-sided p-value of every vector row that is not a tie, in the small grid
/// and the 20/30 rows, to 1e-10, with `p < ALPHA` agreeing on each.
/// Oracle: scipy `fisher_exact(.., alternative="two-sided")`.
/// Bite: twice the smaller tail in place of the sum of the tables no more likely than the
/// observed one.
#[test]
fn t1_fisher_two_sided_matches_the_second_engine() {
    let rows = vector::<FisherRow>("fisher.toml");
    let plain: Vec<&FisherRow> = rows.iter().filter(|row| !row.tie).collect();
    assert!(
        plain.len() > 400,
        "the vector holds {} plain rows",
        plain.len()
    );
    for row in plain {
        check_fisher(row);
    }
}

/// Guards: the rows where scipy's relative tolerance on equal table probabilities decides the
/// p-value (the strict sum differs from scipy's by more than 1e-9). At least five exist.
/// Oracle: scipy `fisher_exact`, read at the version recorded in `fisher.toml`.
/// Bite: the tie tolerance set to 0.
#[test]
fn t1_fisher_ties_follow_the_tolerance() {
    let rows = vector::<FisherRow>("fisher.toml");
    let ties: Vec<&FisherRow> = rows.iter().filter(|row| row.tie).collect();
    assert!(ties.len() >= 5, "the vector holds {} tie rows", ties.len());
    for row in ties {
        check_fisher(row);
    }
}

/// Guards: the tie tolerance of Fisher's test is a deliberate choice between scipy's 1e-14 and
/// R's 1e-7. Over every pair of tables that the margins of `fisher.toml` compare, no two exact
/// hypergeometric probabilities differ relatively by more than 1e-14 and less than 1e-7, so the
/// choice changes no p-value on the grid; the vector records that count and its bounds.
/// Oracle: exact rationals (`fractions.Fraction` over `math.comb`) in `gen_stats.py`, which
/// `--check` regenerates and compares.
/// Bite: the tolerance set to 0, or to 1e-14 (the equal-arm rows go red under the distribution
/// library's rounding); a planted near-tie, which `--check` flags.
#[test]
fn t1_the_tie_tolerance_changes_no_vector_value() {
    #[derive(Deserialize)]
    struct Window {
        lower: f64,
        upper: f64,
        near_ties: u64,
    }
    #[derive(Deserialize)]
    struct File {
        ties: Window,
    }
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors/stats/fisher.toml");
    let text = std::fs::read_to_string(&path).expect("fisher.toml");
    let file: File = toml::from_str(&text).expect("the [ties] table");
    assert_eq!(
        file.ties.near_ties, 0,
        "tables with near-equal probabilities exist on the grid"
    );
    assert!(
        file.ties.lower < TIE_TOLERANCE,
        "the tolerance is not above scipy's"
    );
    assert!(
        TIE_TOLERANCE <= file.ties.upper,
        "the tolerance {TIE_TOLERANCE:e} reaches beyond the checked window {:e}",
        file.ties.upper
    );
}

/// Guards: Newcombe's hybrid score difference and both limits for 576 pairs of counts, to 1e-9,
/// so the Wald difference interval, a continuity correction or a swapped limit is seen.
/// Oracle: statsmodels `confint_proportions_2indep(method="newcomb", compare="diff")`, which
/// the generator re-derived from scipy's Wilson limits with Newcombe's formula.
/// Bite: the Wald difference interval in place of Newcombe's.
#[test]
fn t1_newcombe_matches_the_second_engine() {
    for row in vector::<NewcombeRow>("newcombe.toml") {
        let label = format!("newcombe {}/{} minus {}/{}", row.k1, row.n1, row.k2, row.n2);
        let got = newcombe_difference(counts(row.k1, row.n1), counts(row.k2, row.n2))
            .unwrap_or_else(|e| panic!("{label}: {e}"));
        close(&format!("{label} diff"), got.diff(), row.diff, 1e-9);
        close(&format!("{label} lo"), got.lo(), row.lo, 1e-9);
        close(&format!("{label} hi"), got.hi(), row.hi, 1e-9);
    }
}

/// Guards: Holm's adjusted values for 212 lists (ties, zeros, ones, capped values, adjusted
/// values equal to alpha, m = 20), in the input order, to 1e-12.
/// Oracle: statsmodels `multipletests(method="holm")`.
/// Bite: Holm without the step-down maximum.
#[test]
fn t1_holm_matches_the_second_engine() {
    for (index, row) in vector::<HolmRow>("holm.toml").into_iter().enumerate() {
        let got = holm(&row.p).unwrap_or_else(|e| panic!("holm row {index}: {e}"));
        assert_eq!(got.len(), row.adjusted.len(), "holm row {index}: length");
        for (position, (have, want)) in got.iter().zip(&row.adjusted).enumerate() {
            close(
                &format!("holm row {index} position {position} of {:?}", row.p),
                *have,
                *want,
                1e-12,
            );
        }
    }
}

/// Guards: the edges. `k = 0`, `k = n` and `n = 1` give limits inside [0, 1] with the touched
/// limit at its bound; `n = 0` is a count that every method refuses; `k` above `n`, a count
/// above 2^53, and a `NaN`, infinite or out-of-range p-value are refused with their own errors;
/// an empty list adjusts to an empty list; `rejected` is strict (an adjusted value equal to
/// alpha does not reject).
/// Oracle: hand values from the definitions (Wilson's `k = 0` lower limit is 0; at n = 1 the
/// upper limit for k = 0 is z²/(1 + z²) = 0.7934507, and the lower limit for k = 1 is its
/// complement 0.2065493).
/// Bite: limits not clamped; `rejected` written with `<=`.
#[test]
fn t1_edges_hold() {
    // k = 0 and k = n.
    let low = wilson(counts(0, 5)).expect("0/5");
    assert!(low.lo() >= 0.0 && low.lo() < 1e-12, "lo = {:?}", low.lo());
    let high = wilson(counts(5, 5)).expect("5/5");
    assert!(
        high.hi() <= 1.0 && high.hi() > 1.0 - 1e-12,
        "hi = {:?}",
        high.hi()
    );
    // Rounding must not push a limit outside [0, 1] for any n up to 200.
    for n in 1..=200_u64 {
        for k in [0, n] {
            let interval = wilson(counts(k, n)).expect("an interval");
            assert!(
                (0.0..=1.0).contains(&interval.lo()) && (0.0..=1.0).contains(&interval.hi()),
                "{k}/{n}: [{:?}, {:?}]",
                interval.lo(),
                interval.hi()
            );
        }
    }
    // n = 1.
    let none = wilson(counts(0, 1)).expect("0/1");
    close("0/1 hi", none.hi(), 0.793_450_7, 1e-6);
    let one = wilson(counts(1, 1)).expect("1/1");
    close("1/1 lo", one.lo(), 0.206_549_3, 1e-6);
    // Newcombe's limits stay in [-1, 1].
    let extreme = newcombe_difference(counts(5, 5), counts(0, 5)).expect("5/5 minus 0/5");
    assert!(extreme.hi() <= 1.0 && extreme.lo() >= -1.0);
    close("5/5 minus 0/5 diff", extreme.diff(), 1.0, 1e-15);

    // n = 0 is a count; each method refuses it.
    let empty = counts(0, 0);
    assert_eq!(empty.n(), 0);
    assert_eq!(wilson(empty), Err(StatsError::NoRuns));
    assert_eq!(
        fisher_two_sided(empty, counts(1, 2)),
        Err(StatsError::NoRuns)
    );
    assert_eq!(
        fisher_two_sided(counts(1, 2), empty),
        Err(StatsError::NoRuns)
    );
    assert_eq!(
        newcombe_difference(counts(1, 2), empty),
        Err(StatsError::NoRuns)
    );

    // Refused counts.
    assert_eq!(
        Counts::new(3, 2),
        Err(StatsError::CountAboveRuns { k: 3, n: 2 })
    );
    let limit = 1_u64 << 53;
    assert!(Counts::new(limit, limit).is_ok());
    assert_eq!(
        Counts::new(0, limit + 1),
        Err(StatsError::CountTooLarge { n: limit + 1 })
    );

    // Refused p-values, with the index of the first.
    for (list, index) in [
        (vec![0.5, f64::NAN], 1),
        (vec![-0.1], 0),
        (vec![0.2, 0.3, 1.000_000_1], 2),
        (vec![f64::INFINITY], 0),
        (vec![f64::NEG_INFINITY, 0.5], 0),
    ] {
        assert_eq!(
            holm(&list),
            Err(StatsError::NotAProbability { index }),
            "{list:?}"
        );
    }
    assert_eq!(holm(&[]), Ok(Vec::new()));

    // `rejected` is strict.
    assert_eq!(
        rejected(&[ALPHA, 0.049_999_9, 0.0, 1.0]),
        vec![false, true, true, false]
    );
}

// ---- T3: the rate algebra ----------------------------------------------------------------------

const EVALUATOR: &str = "live-eval@0.5.0";

fn digest(c: char) -> Digest {
    format!("sha256:{}", String::from(c).repeat(64))
        .parse()
        .expect("a digest")
}

fn evaluator() -> NameVersion {
    EVALUATOR.parse().expect("an evaluator")
}

fn run(cell: char, replicate: u32) -> RunKey {
    format!("{}-r{replicate}-a1", String::from(cell).repeat(64))
        .parse()
        .expect("a run key")
}

fn expectation(id: &str) -> ExpectationId {
    id.parse().expect("an expectation id")
}

/// Every record gets its own request id, so the selection keeps them all current.
fn request(n: u64) -> RequestId {
    format!("01926b3a-7c3e-7a1b-8c4d-{n:012x}")
        .parse()
        .expect("a request id")
}

fn reason(code: &str) -> Cause {
    Cause::Reason(code.parse().expect("a reason code"))
}

/// A record of arm `cell`, replicate `replicate`, expectation `id` and role `role`.
fn record(
    n: u64,
    cell: char,
    replicate: u32,
    id: &str,
    role: Role,
    status: Status,
) -> OutcomeRecordBuilder {
    OutcomeRecord::builder()
        .run(run(cell, replicate))
        .expectation_id(expectation(id))
        .role(role)
        .evaluator(evaluator())
        .suite_entry_digest(digest('d'))
        .context_digest(digest('c'))
        .request_id(request(n))
        .status(status)
}

fn gate(n: u64, cell: char, replicate: u32, id: &str, status: Status) -> OutcomeRecordBuilder {
    record(n, cell, replicate, id, Role::Gate, status)
}

fn built(builder: OutcomeRecordBuilder) -> OutcomeRecord {
    builder.build().expect("a valid record")
}

fn valid(cell: char, replicate: u32) -> RunFacts {
    RunFacts::new(run(cell, replicate), Integrity::Valid)
}

fn invalid(cell: char, replicate: u32, why: InvalidReason) -> RunFacts {
    RunFacts::new(run(cell, replicate), Integrity::invalid(why))
}

fn tallied(records: Vec<OutcomeRecord>, runs: &[RunFacts]) -> BTreeMap<CellKey, ArmTally> {
    tally(&select(records), &evaluator(), runs).expect("a tally")
}

fn arm(arms: &BTreeMap<CellKey, ArmTally>, cell: char) -> &ArmTally {
    arms.get(&CellKey::new(digest(cell)))
        .unwrap_or_else(|| panic!("no arm {cell}"))
}

fn counts_of(arm: &ArmTally, id: &str) -> (u64, u64) {
    let counts = arm
        .expectations
        .get(&expectation(id))
        .unwrap_or_else(|| panic!("no expectation {id}"))
        .counts()
        .expect("counts");
    (counts.k(), counts.n())
}

/// Guards: `blocked` is a failure: it is in `n`, never in `k`, and weighs 0/1 in the rate. With
/// two passes, one fail and one blocked, `k/n` is 2/4 and the gate rate 2/4.
/// Oracle: R01's rate rule, hand counts.
/// Bite: `blocked` left out of `n`.
#[test]
fn t3_blocked_counts_as_a_failure() {
    let records = vec![
        built(gate(1, 'a', 1, "E1", Status::Pass)),
        built(gate(2, 'a', 2, "E1", Status::Blocked).cause(reason("missing_input"))),
        built(gate(3, 'a', 3, "E1", Status::Fail)),
        built(gate(4, 'a', 4, "E1", Status::Pass)),
    ];
    let runs: Vec<RunFacts> = (1..=4).map(|r| valid('a', r)).collect();
    let arms = tallied(records, &runs);
    let a = arm(&arms, 'a');
    let e1 = a.expectations.get(&expectation("E1")).expect("E1");
    assert_eq!((e1.pass, e1.fail, e1.blocked), (2, 1, 1));
    assert_eq!(counts_of(a, "E1"), (2, 4));
    let rate = a.rate(Role::Gate);
    assert_eq!((rate.num(), rate.den()), (2, 4));
}

/// Guards: a run's expectation counts once per evaluator, by its latest record, when a regrade
/// gave it another context digest or another suite entry digest: a blocked outcome under the
/// empty context then a pass under the real one is 1/1, and a fail under one suite entry then a
/// pass under its edited params is 1/1, in `n`, `k`, the gate rate and `rates`.
/// Oracle: R01's rate rule, hand counts.
/// Bite: every current record under its I4 key counted, which gives 2/4.
#[test]
fn t3_regraded_outcomes_count_once() {
    let records = vec![
        built(
            gate(1, 'a', 1, "E1", Status::Blocked)
                .cause(reason("missing_input"))
                .context_digest(digest('e')),
        ),
        built(gate(2, 'a', 1, "E1", Status::Pass)),
        built(gate(3, 'a', 2, "E1", Status::Fail).suite_entry_digest(digest('f'))),
        built(gate(4, 'a', 2, "E1", Status::Pass)),
    ];
    let runs: Vec<RunFacts> = (1..=2).map(|r| valid('a', r)).collect();
    let selection = select(records);
    let arms = tally(&selection, &evaluator(), &runs).expect("a tally");
    let a = arm(&arms, 'a');
    assert_eq!(counts_of(a, "E1"), (2, 2));
    let rate = a.rate(Role::Gate);
    assert_eq!((rate.num(), rate.den()), (2, 2));
    let sums = rates(&selection, &evaluator());
    assert_eq!(
        sums.get(&CellKey::new(digest('a'))).map(Rates::gate),
        Some((2, 2))
    );
}

/// Guards: `not_measured` and `not_applicable` are out of `n` and counted with their causes
/// (`reason:`, `artifact:`, `expectation:` keys); two instrument errors, one deadline and two
/// applicability causes leave `n` at the one graded run.
/// Oracle: R01's rate rule, hand counts.
/// Bite: `not_applicable` put in `n`.
#[test]
fn t3_excluded_statuses_are_counted_with_their_causes() {
    let artifact = Cause::Artifact("out/plan.json".parse().expect("a path"));
    let upstream = Cause::Expectation(expectation("E0"));
    let records = vec![
        built(gate(1, 'a', 1, "E1", Status::Pass)),
        built(gate(2, 'a', 2, "E1", Status::NotMeasured).cause(reason("instrument_error"))),
        built(gate(3, 'a', 3, "E1", Status::NotMeasured).cause(reason("instrument_error"))),
        built(gate(4, 'a', 4, "E1", Status::NotMeasured).cause(reason("deadline"))),
        built(gate(5, 'a', 5, "E1", Status::NotApplicable).cause(artifact)),
        built(gate(6, 'a', 6, "E1", Status::NotApplicable).cause(upstream)),
    ];
    let runs: Vec<RunFacts> = (1..=6).map(|r| valid('a', r)).collect();
    let arms = tallied(records, &runs);
    let a = arm(&arms, 'a');
    let e1 = a.expectations.get(&expectation("E1")).expect("E1");
    assert_eq!(counts_of(a, "E1"), (1, 1));
    assert_eq!(
        e1.not_measured,
        BTreeMap::from([
            ("reason:instrument_error".to_owned(), 2),
            ("reason:deadline".to_owned(), 1)
        ])
    );
    assert_eq!(
        e1.not_applicable,
        BTreeMap::from([
            ("artifact:out/plan.json".to_owned(), 1),
            ("expectation:E0".to_owned(), 1)
        ])
    );
    let rate = a.rate(Role::Gate);
    assert_eq!((rate.num(), rate.den()), (1, 1));
}

/// Guards: an invalid run is out of `k` and `n` in its own arm only, and is counted once by run
/// key with its reason, whatever its records (it may have several, or none). Another arm's
/// counts do not move.
/// Oracle: I10, hand counts.
/// Bite: the records of an invalid run counted anyway.
#[test]
fn t3_invalid_runs_are_out_per_arm_with_their_reason() {
    let records = vec![
        built(gate(1, 'a', 1, "E1", Status::Pass)),
        // Run a2 is invalid and has two records, both passes: none may count.
        built(gate(2, 'a', 2, "E1", Status::Pass)),
        built(gate(3, 'a', 2, "E2", Status::Pass)),
        built(gate(4, 'b', 1, "E1", Status::Fail)),
    ];
    let runs = vec![
        valid('a', 1),
        invalid('a', 2, InvalidReason::Gateway),
        // Run a3 is invalid and has no record at all.
        invalid('a', 3, InvalidReason::InputLeak),
        invalid('a', 4, InvalidReason::Gateway),
        valid('b', 1),
    ];
    let arms = tallied(records, &runs);
    let a = arm(&arms, 'a');
    assert_eq!(a.valid_runs, 1);
    assert_eq!(
        a.invalid,
        BTreeMap::from([("gateway".to_owned(), 2), ("input_leak".to_owned(), 1)])
    );
    assert_eq!(counts_of(a, "E1"), (1, 1));
    assert!(
        !a.expectations.contains_key(&expectation("E2")),
        "E2 had records only in the invalid run"
    );
    let b = arm(&arms, 'b');
    assert_eq!((b.valid_runs, b.invalid.len()), (1, 0));
    assert_eq!(counts_of(b, "E1"), (0, 1));
}

/// Guards: a run the experimenter ended (`budget_stop`, `killed`, `interrupted`) is kept in
/// `experimenter_ends` and never in the arm's `invalid`, so no reader sums it as a failure; its
/// records are out of `n`.
/// Oracle: I20.
/// Bite: an experimenter end (`killed`) charged to the arm.
#[test]
fn t3_experimenter_ends_are_not_charged_to_an_arm() {
    let records = vec![
        built(gate(1, 'a', 1, "E1", Status::Pass)),
        built(gate(2, 'a', 2, "E1", Status::Fail)),
        built(gate(3, 'a', 3, "E1", Status::Fail)),
    ];
    let runs = vec![
        valid('a', 1),
        invalid('a', 2, InvalidReason::Killed),
        invalid('a', 3, InvalidReason::BudgetStop),
        invalid('a', 4, InvalidReason::Interrupted),
        invalid('a', 5, InvalidReason::Killed),
        invalid('a', 6, InvalidReason::Infrastructure),
    ];
    let arms = tallied(records, &runs);
    let a = arm(&arms, 'a');
    assert_eq!(
        a.experimenter_ends,
        BTreeMap::from([
            ("budget_stop".to_owned(), 1),
            ("interrupted".to_owned(), 1),
            ("killed".to_owned(), 2)
        ])
    );
    assert_eq!(
        a.invalid,
        BTreeMap::from([("infrastructure".to_owned(), 1)])
    );
    assert_eq!(counts_of(a, "E1"), (1, 1));
}

/// Guards: an expectation with a counted outcome weighing other than 1/1 or 0/1 is not binary:
/// its counts, its Wilson interval and every comparison built on them are omitted with the
/// reason `weighted`, while its rate still sums the weights (3/3 + 0/1 + 1/3 gives 4/7). An
/// expectation of plain outcomes beside it stays binary.
/// Oracle: R01's weight rule, hand sums.
/// Bite: `binary` left true for a weighted outcome.
#[test]
fn t3_weights_make_an_expectation_non_binary() {
    let records = vec![
        built(gate(1, 'a', 1, "W", Status::Pass).weight(Weight::new(3, 3).expect("a weight"))),
        built(gate(2, 'a', 2, "W", Status::Fail)),
        built(gate(3, 'a', 3, "W", Status::Fail).weight(Weight::new(1, 3).expect("a weight"))),
        built(gate(4, 'a', 1, "P", Status::Pass)),
        built(gate(5, 'a', 2, "P", Status::Fail)),
    ];
    let runs: Vec<RunFacts> = (1..=3).map(|r| valid('a', r)).collect();
    let arms = tallied(records, &runs);
    let a = arm(&arms, 'a');
    let weighted = a.expectations.get(&expectation("W")).expect("W");
    assert!(!weighted.binary);
    assert_eq!(weighted.counts(), Err(Omitted::Weighted));
    assert_eq!(weighted.wilson(), Err(Omitted::Weighted));
    assert_eq!(Omitted::Weighted.as_str(), "weighted");
    assert_eq!((weighted.num, weighted.den), (4, 7));
    let plain = a.expectations.get(&expectation("P")).expect("P");
    assert!(plain.binary);
    assert!(plain.wilson().is_ok());
    let rate = a.rate(Role::Gate);
    assert_eq!((rate.num(), rate.den()), (5, 9));
}

/// Guards: a `pass` weighing 0/0 is out of `k`, out of `n` and out of every sum, and is counted
/// in `zero_weight`.
/// Oracle: R01's rate rule (a 0/0 weight adds nothing), hand counts.
/// Bite: a zero-weight pass counted as a pass.
#[test]
#[expect(deprecated, reason = "a zero weight carries the legacy cause")]
fn t3_zero_weight_passes_add_nothing() {
    let legacy = Cause::Legacy("zero_weight".parse().expect("a reason code"));
    let records = vec![
        built(gate(1, 'a', 1, "E1", Status::Pass)),
        built(
            gate(2, 'a', 2, "E1", Status::Pass)
                .weight(Weight::new(0, 0).expect("a weight"))
                .cause(legacy),
        ),
        built(gate(3, 'a', 3, "E1", Status::Fail)),
    ];
    let runs: Vec<RunFacts> = (1..=3).map(|r| valid('a', r)).collect();
    let arms = tallied(records, &runs);
    let a = arm(&arms, 'a');
    let e1 = a.expectations.get(&expectation("E1")).expect("E1");
    assert_eq!(e1.zero_weight, 1);
    assert_eq!((e1.pass, e1.fail), (1, 1));
    assert_eq!(counts_of(a, "E1"), (1, 2));
    assert!(e1.binary, "a zero weight does not make the rest weighted");
    let rate = a.rate(Role::Gate);
    assert_eq!((rate.num(), rate.den()), (1, 2));
}

/// Guards: when every run is valid, each cell's per-role sums equal the existing
/// `evaluation::selection::rates::rates` on the same selection, over gate, quality and
/// descriptive expectations with every status and a weight.
/// Oracle: `rates`, an implementation of the same R01 rule that shares no code with `tally`.
/// Bite: a role's sum taken from the wrong role.
#[test]
fn t3_roles_sum_as_rates_does() {
    let mut n = 0;
    let mut next = || {
        n += 1;
        n
    };
    let mut records = Vec::new();
    for (cell, replicates) in [('a', 4_u32), ('b', 3)] {
        for r in 1..=replicates {
            records.push(built(record(
                next(),
                cell,
                r,
                "G1",
                Role::Gate,
                Status::Pass,
            )));
            records.push(built(record(
                next(),
                cell,
                r,
                "G2",
                Role::Gate,
                if r % 2 == 0 {
                    Status::Fail
                } else {
                    Status::Pass
                },
            )));
            records.push(built(
                record(next(), cell, r, "Q1", Role::Quality, Status::Pass)
                    .weight(Weight::new(2, 2).expect("a weight")),
            ));
            records.push(built(
                record(next(), cell, r, "Q2", Role::Quality, Status::Fail)
                    .weight(Weight::new(r.into(), 5).expect("a weight")),
            ));
            records.push(built(
                record(next(), cell, r, "Q3", Role::Quality, Status::Blocked)
                    .cause(reason("missing_input")),
            ));
            records.push(built(
                record(next(), cell, r, "Q4", Role::Quality, Status::NotApplicable)
                    .cause(reason("not_applicable_to_arm")),
            ));
            records.push(built(
                record(next(), cell, r, "D1", Role::Descriptive, Status::Pass)
                    .value(Value::count(3)),
            ));
        }
    }
    let runs: Vec<RunFacts> = [('a', 4_u32), ('b', 3)]
        .into_iter()
        .flat_map(|(cell, count)| (1..=count).map(move |r| valid(cell, r)))
        .collect();
    let selection = select(records);
    let expected = rates(&selection, &evaluator());
    let arms = tally(&selection, &evaluator(), &runs).expect("a tally");
    assert_eq!(expected.len(), 2);
    for (cell, sums) in &expected {
        let arm = arms.get(cell).expect("the same cells");
        let gate = arm.rate(Role::Gate);
        let quality = arm.rate(Role::Quality);
        assert_eq!((gate.num(), gate.den()), sums.gate(), "gate of {cell}");
        assert_eq!(
            (quality.num(), quality.den()),
            sums.quality(),
            "quality of {cell}"
        );
        let descriptive = arm.rate(Role::Descriptive);
        assert_eq!((descriptive.num(), descriptive.den()), (0, 0));
    }
    // Hand check of cell a: G1 4/4, G2 2/4 (replicates 1 and 3 pass); Q1 weighs 2/2 four times,
    // Q2 weighs r/5 with r from 1 to 4, Q3 weighs 0/1 four times.
    let a = arm(&arms, 'a');
    let gate = a.rate(Role::Gate);
    assert_eq!((gate.num(), gate.den()), (4 + 2, 8));
    let quality = a.rate(Role::Quality);
    assert_eq!(
        (quality.num(), quality.den()),
        (8 + (1 + 2 + 3 + 4), 8 + 20 + 4)
    );
    let d1 = a.expectations.get(&expectation("D1")).expect("D1");
    assert_eq!(d1.pass, 4);
    assert_eq!(d1.counts(), Err(Omitted::Descriptive));
}

/// Guards: no number without its counts. A rate is a pair of counts (a role with nothing
/// counted is 0/0, not a float), an expectation's `k` and `n` are `pass` and `pass + fail +
/// blocked`, `n = 0` is omitted as `no_runs`, and a current record of a run the caller did not
/// list is a refusal, not a guess.
/// Oracle: R01's I2, hand counts.
/// Bite: `n` taken without its blocked outcomes; a record of an unlisted run skipped in
/// silence.
#[test]
fn t3_every_rate_carries_its_counts() {
    let records = vec![
        built(gate(1, 'a', 1, "E1", Status::Pass)),
        built(gate(2, 'a', 2, "E1", Status::Blocked).cause(reason("missing_input"))),
        built(gate(3, 'a', 3, "E2", Status::NotMeasured).cause(reason("instrument_error"))),
    ];
    let runs: Vec<RunFacts> = (1..=3).map(|r| valid('a', r)).collect();
    let arms = tallied(records.clone(), &runs);
    let a = arm(&arms, 'a');
    let e1 = a.expectations.get(&expectation("E1")).expect("E1");
    let counts = e1.counts().expect("counts");
    assert_eq!(
        (counts.k(), counts.n()),
        (e1.pass, e1.pass + e1.fail + e1.blocked)
    );
    assert_eq!((counts.k(), counts.n()), (1, 2));
    let e2 = a.expectations.get(&expectation("E2")).expect("E2");
    assert_eq!(e2.counts(), Err(Omitted::NoRuns));
    assert_eq!(e2.wilson(), Err(Omitted::NoRuns));
    let quality = a.rate(Role::Quality);
    assert_eq!((quality.num(), quality.den()), (0, 0));

    let unlisted = tally(&select(records), &evaluator(), &runs[..2]);
    assert_eq!(
        unlisted,
        Err(candler_core::analysis::error::StatsError::RunNotListed { run: run('a', 3) })
    );
}

// ---- T2: known truth ---------------------------------------------------------------------------

/// Replications per scenario of the simulated guards.
const REPLICATIONS: u64 = 2000;

/// The Monte Carlo allowance on a rate near `p`: two standard errors over `REPLICATIONS`.
fn allowance(p: f64) -> f64 {
    #[expect(
        clippy::as_conversions,
        clippy::cast_precision_loss,
        reason = "REPLICATIONS is 2000"
    )]
    let replications = REPLICATIONS as f64;
    2.0 * (p * (1.0 - p) / replications).sqrt()
}

/// A pass probability as `num / den`, drawn with no float: `next_u64() % den < num`.
fn draw(rng: &mut ChaCha8Rng, num: u64, den: u64) -> bool {
    rng.next_u64() % den < num
}

/// The p-value of every pair `(k1, k2)` of pass counts for two arms of `n` runs, indexed
/// `k1 * (n + 1) + k2`, computed once by calling `fisher_two_sided`.
fn p_table(n: u64) -> Vec<f64> {
    (0..=n)
        .flat_map(|k1| (0..=n).map(move |k2| (k1, k2)))
        .map(|(k1, k2)| fisher_two_sided(counts(k1, n), counts(k2, n)).expect("a p-value"))
        .collect()
}

/// How the runs of one arm pass their expectations.
#[derive(Clone, Copy)]
enum Passing {
    /// Every expectation of every run passes with probability `num / den`, independently.
    Independent { num: u64, den: u64 },
    /// Each run draws a shared flag, good with probability 1/2; its expectations then pass with
    /// probability 4/5 when good and 1/5 when bad.
    Shared,
}

/// The pass counts of one arm over `m` expectations.
fn arm_counts(rng: &mut ChaCha8Rng, n: u64, m: usize, passing: Passing) -> Vec<u64> {
    let mut passes = vec![0_u64; m];
    for _ in 0..n {
        let (num, den) = match passing {
            Passing::Independent { num, den } => (num, den),
            Passing::Shared => {
                if draw(rng, 1, 2) {
                    (4, 5)
                } else {
                    (1, 5)
                }
            }
        };
        for slot in &mut passes {
            if draw(rng, num, den) {
                *slot += 1;
            }
        }
    }
    passes
}

/// The share of `REPLICATIONS` replications of two arms of `n` runs and `m` expectations, the
/// same in both arms, in which Fisher plus Holm rejects at least one null.
fn rejection_share(seed: u64, n: u64, m: usize, passing: Passing) -> f64 {
    let table = p_table(n);
    let width = usize::try_from(n + 1).expect("a small n");
    let mut rng = ChaCha8Rng::seed_from_u64(seed);
    let mut rejecting = 0_u64;
    for _ in 0..REPLICATIONS {
        let first = arm_counts(&mut rng, n, m, passing);
        let second = arm_counts(&mut rng, n, m, passing);
        let p: Vec<f64> = first
            .iter()
            .zip(&second)
            .map(|(k1, k2)| {
                let (k1, k2) = (
                    usize::try_from(*k1).expect("a small count"),
                    usize::try_from(*k2).expect("a small count"),
                );
                table[k1 * width + k2]
            })
            .collect();
        let adjusted = holm(&p).expect("adjusted p-values");
        if rejected(&adjusted).into_iter().any(|r| r) {
            rejecting += 1;
        }
    }
    #[expect(
        clippy::as_conversions,
        clippy::cast_precision_loss,
        reason = "both counts are far below 2^53"
    )]
    let share = rejecting as f64 / REPLICATIONS as f64;
    share
}

#[derive(Deserialize)]
struct CoverageRow {
    n: u64,
    p: f64,
    coverage: f64,
}

#[derive(Deserialize)]
struct PowerRow {
    n: u64,
    p_a: f64,
    p_b: f64,
    alpha: f64,
    power: f64,
}

/// Guards: the exact coverage of the Wilson interval, summed over every k with the binomial
/// probability, equals scipy's table to 1e-9 for n in {5, 10, 30} and p in {0.1, 0.5, 0.9}, and
/// is at least 0.91 in each. The floor is 0.91 and not 0.93 because Wilson itself cannot reach
/// 0.93 at small n: at n = 5, p = 0.1 the exact coverage is 0.9185.
/// Oracle: scipy's `binom.pmf` over statsmodels' Wilson limits, in `coverage.toml`.
/// Bite: Wilson with a continuity correction (the equality goes red); the Wald interval (the
/// floor goes red).
#[test]
fn t2_wilson_coverage_is_exact() {
    let rows = vector::<CoverageRow>("coverage.toml");
    assert_eq!(rows.len(), 9);
    for row in rows {
        let binomial = Binomial::new(row.p, row.n).expect("a binomial");
        let coverage: f64 = (0..=row.n)
            .map(|k| {
                let interval = wilson(counts(k, row.n)).expect("an interval");
                if interval.lo() <= row.p && row.p <= interval.hi() {
                    binomial.pmf(k)
                } else {
                    0.0
                }
            })
            .sum();
        let label = format!("coverage at n = {}, p = {}", row.n, row.p);
        close(&label, coverage, row.coverage, 1e-9);
        assert!(
            coverage >= 0.91,
            "{label}: {coverage:?} is below the floor 0.91"
        );
    }
}

/// Guards: with the same pass probability in both arms, so that every null is true, Fisher plus
/// Holm rejects something in at most 0.05 + 2 standard errors of 2,000 seeded replications, for
/// n in {5, 10, 30}, m in {1, 5, 20} and p in {1/5, 1/2}, and for a scenario of strongly
/// correlated expectations (n = 10, m = 20, a shared run-level flag). The observed rates are
/// printed.
/// Oracle: the truth of the simulation (no difference was planted), with the Monte Carlo
/// allowance as the bound.
/// Bite: Holm replaced by the identity.
#[test]
fn t2_family_wise_error_holds_under_h0() {
    let bound = 0.05 + allowance(0.05);
    let mut scenario = 0_u64;
    for n in [5_u64, 10, 30] {
        for m in [1_usize, 5, 20] {
            for (num, den) in [(1_u64, 5_u64), (1, 2)] {
                let share = rejection_share(scenario, n, m, Passing::Independent { num, den });
                eprintln!("fwer n={n} m={m} p={num}/{den} seed={scenario}: {share:.4}");
                assert!(
                    share <= bound,
                    "n={n} m={m} p={num}/{den}: family-wise error {share:.4} exceeds {bound:.4}"
                );
                scenario += 1;
            }
        }
    }
    let share = rejection_share(scenario, 10, 20, Passing::Shared);
    eprintln!("fwer n=10 m=20 correlated seed={scenario}: {share:.4}");
    assert!(
        share <= bound,
        "correlated scenario: family-wise error {share:.4} exceeds {bound:.4}"
    );
}

/// Guards: the positive control. With p = 1/5 against 4/5 over n = 10 runs, the exact power of
/// Fisher's test (the Rust sum over every pair of counts) equals scipy's value to 1e-9, and the
/// simulated rejection rate through Fisher and Holm at m = 1 is at least that power minus 2
/// standard errors.
/// Oracle: scipy's `fisher_exact` and `binom.pmf` in `power.toml`.
/// Bite: a test that never rejects (the power control goes red).
#[test]
fn t2_power_is_found() {
    let rows = vector::<PowerRow>("power.toml");
    let row = rows.first().expect("one row");
    assert_eq!((row.n, row.p_a, row.p_b, row.alpha), (10, 0.2, 0.8, ALPHA));
    let low = Binomial::new(row.p_a, row.n).expect("a binomial");
    let high = Binomial::new(row.p_b, row.n).expect("a binomial");
    let power: f64 = (0..=row.n)
        .flat_map(|k1| (0..=row.n).map(move |k2| (k1, k2)))
        .filter(|(k1, k2)| {
            fisher_two_sided(counts(*k1, row.n), counts(*k2, row.n)).expect("a p-value") < ALPHA
        })
        .map(|(k1, k2)| low.pmf(k1) * high.pmf(k2))
        .sum();
    close("exact power", power, row.power, 1e-9);

    let table = p_table(10);
    let mut rng = ChaCha8Rng::seed_from_u64(1_000);
    let mut rejecting = 0_u64;
    for _ in 0..REPLICATIONS {
        let k1 = arm_counts(&mut rng, 10, 1, Passing::Independent { num: 1, den: 5 });
        let k2 = arm_counts(&mut rng, 10, 1, Passing::Independent { num: 4, den: 5 });
        let (k1, k2) = (
            usize::try_from(k1.first().copied().expect("one count")).expect("small"),
            usize::try_from(k2.first().copied().expect("one count")).expect("small"),
        );
        let adjusted = holm(&[table[k1 * 11 + k2]]).expect("adjusted");
        if rejected(&adjusted).into_iter().any(|r| r) {
            rejecting += 1;
        }
    }
    #[expect(
        clippy::as_conversions,
        clippy::cast_precision_loss,
        reason = "both counts are far below 2^53"
    )]
    let rate = rejecting as f64 / REPLICATIONS as f64;
    eprintln!("power: exact {power:.4}, simulated {rate:.4}");
    assert!(
        rate >= power - allowance(power),
        "simulated power {rate:.4} is below {:.4}",
        power - allowance(power)
    );
}
